"""The domain registry.

Every field a research question can fall into has an entry here.  Each entry
carries the knowledge a specialist sub-agent needs to work well in that field:
what the field studies, how good research in it is done, which kinds of sources
carry weight, and the keywords used by the offline router.

A ``general`` catch-all guarantees that *no* question is ever rejected for being
outside the catalogue - the system is open to any topic.
"""
from __future__ import annotations

from dataclasses import dataclass, field


@dataclass(frozen=True)
class Domain:
    id: str
    name: str
    category: str
    description: str
    methods: str                    # how to research well in this field
    sources: str                    # the kinds of evidence that carry weight
    keywords: tuple[str, ...] = field(default_factory=tuple)

    def one_liner(self) -> str:
        return f"{self.id}: {self.name} - {self.description}"


def _d(id, name, category, description, methods, sources, keywords):  # noqa: A002 - compact builder
    return Domain(id, name, category, description, methods, sources, tuple(keywords))


