_BY_ID = {d.id: d for d in DOMAINS}


def get_domain(domain_id: str) -> Domain:
    return _BY_ID.get(domain_id, _BY_ID["general"])


def list_domains(category: str | None = None) -> list[Domain]:
    if category is None:
        return list(DOMAINS)
    cat = category.lower()
    return [d for d in DOMAINS if d.category.lower().startswith(cat)]


def categories() -> list[str]:
    seen: list[str] = []
    for d in DOMAINS:
        if d.category not in seen:
            seen.append(d.category)
    return seen


def catalogue_text() -> str:
    """Compact listing handed to the planner so it can pick domain ids."""
    lines = []
    current = None
    for d in DOMAINS:
        if d.category != current:
            current = d.category
            lines.append(f"## {current}")
        lines.append(f"- {d.one_liner()}")
    return "\n".join(lines)
